CREATE TABLE IF NOT EXISTS professions (
    id                INTEGER PRIMARY KEY
  , name              TEXT    NOT NULL UNIQUE
  , parent_id         INTEGER                 -- Starting professions have no parent profession
  , can_be_subclassed BOOLEAN NOT NULL
  , minimum_level     INTEGER NOT NULL CHECK (minimum_level     >= 1)
  , max_hp            DOUBLE  NOT NULL CHECK (max_hp            >= 0)
  , max_mp            DOUBLE  NOT NULL CHECK (max_mp            >= 0)
  , max_cp            DOUBLE  NOT NULL CHECK (max_cp            >= 0)
  , hp_flat_per_level DOUBLE  NOT NULL CHECK (hp_flat_per_level >= 0)
  , mp_flat_per_level DOUBLE  NOT NULL CHECK (mp_flat_per_level >= 0)
  , cp_flat_per_level DOUBLE  NOT NULL CHECK (cp_flat_per_level >= 0)
  , hp_mult_per_level DOUBLE  NOT NULL CHECK (hp_mult_per_level >= 0)
  , mp_mult_per_level DOUBLE  NOT NULL CHECK (mp_mult_per_level >= 0)
  , cp_mult_per_level DOUBLE  NOT NULL CHECK (cp_mult_per_level >= 0)
);

